#[test]
fn udeps() {
    if !is_nightly() {
        #[allow(clippy::explicit_write)]
        writeln!(
            stderr(),
            "Skipping `udeps` test since toolchain is not nightly."
        )
        .unwrap();
        return;
    }

    Command::new("cargo")
        .args(["udeps", "--features=test-install", "--all-targets"])
        .current_dir("..")
        .logged_assert()
        .success();
}

fn is_nightly() -> bool {
    Command::new("rustc")
        .args(["-Z", "help"])
        .stderr(Stdio::null())
        .status()
        .unwrap()
        .success()
}

